mapper.select:
SELECT a.ticket_no AS ticketNo, a.order_no AS orderNo, a.store_id AS storeId, s.store_name AS storeName, a.after_sale_type AS afterSaleType, a.apply_reason AS applyReason, a.evidence_images AS evidenceImages, a.ai_audit_result AS aiAuditResult, a.ai_confidence AS aiConfidence, a.ticket_status AS ticketStatus, a.created_at AS createdAt FROM after_sale_order a LEFT JOIN store_info s ON a.store_id = s.id LEFT JOIN order_info o ON a.order_id = o.id
AND a.order_no = #{orderNo}
AND o.user_phone LIKE CONCAT(#{userPhone}, '%')
AND a.store_id = #{storeId}
AND a.after_sale_type = #{afterSaleType}
AND a.ticket_status = #{ticketStatus}
AND a.created_at >= CONCAT(#{startTime}, ' 00:00:00')
AND a.created_at <= CONCAT(#{endTime}, ' 23:59:59')
ORDER BY a.created_at DESC
